import { observeWorkspaceTheme, workspaceRuntimeConfig, workspaceTheme } from "/runtime/plugin-sdk.js";
import { confirmQuestion, installHistoryControls } from "./history-controls.js";
import "./export-controls.js";

const { apiBaseUrl: api } = workspaceRuntimeConfig();
const applyTheme = (theme) => { document.documentElement.dataset.theme = theme; };
applyTheme(workspaceTheme());
observeWorkspaceTheme(applyTheme);

document.body.innerHTML = `
  <div class="workspace" id="workspace">
    <header class="workspace-header"><div class="header-inner"><div class="brand-lockup"><span class="source-mark" aria-hidden="true">PH</span><div class="brand-copy"><strong>Product Hunt</strong><span>Source Board / Today's launches</span></div></div><div class="header-actions"><button id="refresh" class="icon-button" type="button" aria-label="Refresh Product Hunt" title="Refresh"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11a8.1 8.1 0 0 0-15.5-2M4 4v5h5M4 13a8.1 8.1 0 0 0 15.5 2M20 20v-5h-5"/></svg></button><button id="settings" class="icon-button" type="button" aria-label="Open refresh settings" title="Refresh settings"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l-2.83 2.83A1.7 1.7 0 0 0 14 20.9h-4A1.7 1.7 0 0 0 9 19.36l-2.83 2.83A1.7 1.7 0 0 0 4.63 15 1.7 1.7 0 0 0 3.08 14v-4A1.7 1.7 0 0 0 4.64 9a1.7 1.7 0 0 0-.34-1.88l2.83-2.83A1.7 1.7 0 0 0 9 4.63 1.7 1.7 0 0 0 10 3.08h4A1.7 1.7 0 0 0 15 4.64l2.83-2.83A1.7 1.7 0 0 0 19.37 9 1.7 1.7 0 0 0 20.92 10v4A1.7 1.7 0 0 0 19.4 15Z"/></svg></button></div></div></header>
    <main class="workspace-main"><section class="intro-row" aria-labelledby="workspace-title"><div class="intro-copy"><p class="eyebrow">SOURCE BOARD / PRODUCT HUNT</p><h1 id="workspace-title">把今日发布排成一张决策板。</h1><p class="intro-lede">按排名和投票数比较产品，打开详情查看来源页。Browser Bridge 的依赖状态保持可见，失败时仍保留上次成功结果。</p></div><div class="view-model-note"><span class="note-label">VIEW MODEL</span><strong>launches + votes</strong><span>rank · name · votes · dependency state</span></div></section><div class="prototype-status" role="status" aria-live="polite"><span id="status-dot" class="status-dot"></span><strong id="status-label">Reading retained launches</strong><span id="status-detail"></span></div><div id="warning" class="warning" role="alert" hidden><span><strong>Refresh failed.</strong> Showing the last retained launch board.</span><button id="retry" class="text-button" type="button">Retry</button></div><section id="dependency" class="dependency-panel" hidden><span class="state-mark" aria-hidden="true">PH</span><p class="section-kicker">SOURCE DEPENDENCY</p><h2>Browser connection needed</h2><p id="dependency-copy">Connect OpenCLI Browser Bridge to collect today's ranked launches.</p><div class="dependency-actions"><button id="dependency-retry" class="button button--primary" type="button">Check connection</button><button id="dependency-recover" class="button" type="button">Open Product Hunt</button></div></section><section id="board-area"><div class="board-toolbar"><div><p class="section-kicker">01 / DAILY BOARD</p><h2>Today's top launches</h2></div><div class="board-meta"><strong id="product-count">—</strong><span>launches retained</span></div></div><section id="products" class="board-grid" aria-live="polite"><div class="loading-card">Reading retained launches…</div></section></section><section id="empty" class="state-panel" hidden><span class="state-mark" aria-hidden="true">PH</span><h2 id="empty-title">No retained launches yet</h2><p id="empty-copy">Refresh once to keep today's ranking on this device.</p><button id="empty-refresh" class="button button--primary" type="button">Refresh now</button></section></main>
  </div>
  <div id="scrim" class="scrim" hidden></div>
  <aside id="sheet" class="sheet" role="dialog" aria-modal="true" aria-labelledby="settings-title" hidden><header class="sheet-head"><div><p class="sheet-kicker">WORKSPACE SETTINGS</p><h2 id="settings-title">Refresh settings</h2></div><button id="close-settings" class="icon-button" type="button" aria-label="Close settings">×</button></header><form id="settings-form"><fieldset><legend>Refresh policy</legend><label><input type="radio" name="policy" value="manual"><span>Manual only</span></label><label><input type="radio" name="policy" value="disabled"><span>Refresh disabled</span></label><label><input type="radio" name="policy" value="fixed"><span>Fixed interval</span></label></fieldset><label class="select-field" for="interval">Refresh interval</label><select id="interval" name="intervalMinutes"><option value="15">Every 15 minutes</option><option value="30">Every 30 minutes</option><option value="60">Every hour</option><option value="360">Every 6 hours</option><option value="720">Every 12 hours</option><option value="1440">Every day</option></select><label class="select-field" for="retention">History retention</label><select id="retention" name="retentionDays"><option value="7">7 days</option><option value="30">30 days</option><option value="90">90 days</option></select><div class="sheet-actions"><button id="cancel-settings" class="button" type="button">Cancel</button><button class="button button--primary" type="submit">Save</button></div></form></aside>
  <aside id="detail-sheet" class="detail-sheet" role="dialog" aria-modal="true" aria-labelledby="detail-title" hidden><header class="detail-head"><div><p id="detail-context" class="sheet-kicker">Product Hunt</p><h2 id="detail-title">Launch</h2></div><button id="close-detail" class="icon-button" type="button" aria-label="Close details">×</button></header><div class="detail-body"><div id="detail-meta" class="detail-meta"></div><p id="detail-description" class="detail-description">Product Hunt launch</p><div class="detail-actions"><button id="detail-open" class="button button--primary" type="button">Open in Product Hunt</button></div></div></aside>
`;

document.querySelector(".brand-copy span").id = "refresh-time";
const $ = (selector) => document.querySelector(selector);
let data;
let historyView;
let refreshing = false;
let detailTrigger;
let historyControls;

async function request(route, options = {}) { const response = await fetch(new URL(route.replace(/^\/+/, ""), api), options); if (!response.ok) throw new Error(`Plugin API returned ${response.status}`); return response.json(); }
function normalizeProduct(product) { const fields = product?.fields ?? {}; return { name: product?.name ?? product?.title ?? "", url: product?.url ?? "", rank: product?.rank ?? 0, votes: product?.votes ?? fields.votes ?? 0, read: Boolean(product?.read) }; }
function products() { return (historyView ?? data?.products ?? []).map(normalizeProduct); }
function compact(value) { return new Intl.NumberFormat("en", { notation: "compact", maximumFractionDigits: 1 }).format(value ?? 0); }
function formatTime(value) { return value ? `Updated ${new Intl.DateTimeFormat("en", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(value))}` : "Not refreshed yet"; }

function modal(show, element) { $("#workspace").inert = show; $("#scrim").hidden = !show; element.hidden = !show; }
function showDetail(product, readOnly = false) { detailTrigger = document.activeElement; $("#detail-context").textContent = readOnly ? "Product Hunt / History" : "Product Hunt"; $("#detail-title").textContent = product.name; $("#detail-meta").replaceChildren(...[`Rank ${product.rank}`, `${compact(product.votes)} votes`].map((value) => { const item = document.createElement("span"); item.textContent = value; return item; })); $("#detail-description").textContent = readOnly ? "Historical launch record." : "Today's Product Hunt launch."; $("#detail-open").onclick = () => window.open(product.url, "_blank", "noopener"); modal(true, $("#detail-sheet")); $("#close-detail").focus(); }
function closeDetail() { const trigger = detailTrigger; detailTrigger = undefined; $("#detail-sheet").hidden = true; $("#scrim").hidden = true; $("#workspace").inert = false; if (trigger?.isConnected) trigger.focus(); }

function productCard(product, index, readOnly = false) {
  const card = document.createElement("article");
  const variant = index === 0 ? " board-card--lead" : index === 1 ? " board-card--tall" : index === 2 ? " board-card--wide" : "";
  card.className = `board-card${variant}${product.read ? " is-read" : ""}`;
  card.dataset.productUrl = product.url;
  const top = document.createElement("div"); top.className = "card-topline";
  const rank = document.createElement("span"); rank.textContent = `#${String(product.rank).padStart(2, "0")}`;
  const votes = document.createElement("span"); votes.textContent = `${compact(product.votes)} votes`;
  top.append(rank, votes);
  const action = document.createElement("button"); action.className = "card-action"; action.type = "button"; action.setAttribute("aria-label", `Open ${product.name}`);
  const title = document.createElement("h2"); title.textContent = product.name;
  const description = document.createElement("p"); description.textContent = "Product Hunt launch";
  action.append(title, description); action.onclick = async () => { showDetail(product, readOnly); if (!readOnly) { data = await request(`read?url=${encodeURIComponent(product.url)}`, { method: "POST" }).catch(() => data); render(data); } };
  const footer = document.createElement("div"); footer.className = "card-footer";
  const source = document.createElement("span"); source.textContent = "producthunt.com";
  const state = document.createElement("span"); state.textContent = product.read ? "Read" : "Unread";
  footer.append(source, state); card.append(top, action, footer); return card;
}

function renderDependency() { const disconnected = data?.dependencyState === "disconnected"; $("#dependency").hidden = !disconnected; $("#board-area").hidden = disconnected; $("#empty").hidden = true; if (!disconnected) return; $("#dependency-copy").textContent = "Connect OpenCLI Browser Bridge to collect today's ranked launches."; $("#dependency-recover").onclick = () => window.open("https://chromewebstore.google.com/detail/opencli/ildkmabpimmkaediidaifkhjpohdnifk", "_blank", "noopener"); }
function setStatus(items) { const state = refreshing ? "refreshing" : data?.lastError ? "stale" : items.length ? "ready" : "empty"; const labels = { ready: "Ready", refreshing: "Refreshing", stale: "Showing retained content", empty: "Waiting for first refresh" }; const details = { ready: formatTime(data?.lastSuccessfulRefresh), refreshing: "Task queued", stale: "Refresh failed; previous result retained", empty: "No local launch records" }; $("#status-label").textContent = labels[state]; $("#status-detail").textContent = details[state]; $("#status-dot").dataset.state = state; }
function render(next) { data = next ?? data ?? { products: [] }; const items = products(); renderDependency(); const disconnected = data.dependencyState === "disconnected"; $("#products").replaceChildren(...items.map((product, index) => productCard(product, index, Boolean(historyView)))); $("#products").hidden = !items.length; $("#empty").hidden = disconnected || items.length > 0; $("#empty-title").textContent = data.lastError ? "Unable to read launches" : "No retained launches yet"; $("#empty-copy").textContent = data.lastError ? "Check the Browser Bridge connection and retry." : "Refresh once to keep today's ranking on this device."; $("#empty-refresh").textContent = data.lastError ? "Retry" : "Refresh now"; $("#warning").hidden = !(data.lastError && items.length && !disconnected); $("#product-count").textContent = String(items.length); $("#refresh-time").textContent = formatTime(data.lastSuccessfulRefresh); $("#refresh").disabled = refreshing || data.settings?.policy === "disabled"; setStatus(items); }

async function refresh() { if (refreshing) return; historyControls?.clear(); historyView = undefined; refreshing = true; render(data); try { const refreshed = await request("refresh", { method: "POST" }); data = await request("summary").catch(() => refreshed); } catch (error) { const latest = await request("summary").catch(() => data ?? { products: [] }); data = { ...latest, lastError: latest?.lastError ?? error.message }; } finally { refreshing = false; render(data); } }
function showSettings(show) { $("#workspace").inert = show; $("#sheet").hidden = !show; $("#scrim").hidden = !show; if (show && data?.settings) { document.querySelector(`[name=policy][value=${data.settings.policy}]`).checked = true; $("#interval").value = data.settings.intervalMinutes; $("#retention").value = data.settings.retentionDays; $("#interval").disabled = data.settings.policy !== "fixed"; $("#sheet input:checked").focus(); } else if (!show) $("#settings").focus(); }

$("#refresh").onclick = $("#retry").onclick = $("#empty-refresh").onclick = $("#dependency-retry").onclick = refresh;
$("#settings").onclick = () => showSettings(true); $("#close-settings").onclick = $("#cancel-settings").onclick = () => showSettings(false); $("#close-detail").onclick = closeDetail; $("#scrim").onclick = () => $("#detail-sheet").hidden ? showSettings(false) : closeDetail();
document.querySelectorAll("[name=policy]").forEach((radio) => radio.onchange = () => { $("#interval").disabled = radio.value !== "fixed"; });
$("#settings-form").onsubmit = async (event) => { event.preventDefault(); const form = new FormData(event.currentTarget); const retentionDays = Number(form.get("retentionDays")); const shorter = retentionDays < data.settings.retentionDays; if (shorter && !await confirmQuestion("Shortening history retention deletes older snapshots. Continue?", "Continue", "Cancel")) return; await request(`settings?policy=${form.get("policy")}&intervalMinutes=${form.get("intervalMinutes")}&retentionDays=${retentionDays}&acknowledgeRetentionCleanup=${shorter}`, { method: "POST" }); data = await request("summary"); render(data); showSettings(false); };
addEventListener("keydown", (event) => { if (event.key === "Escape") { if (!$("#detail-sheet").hidden) closeDetail(); else if (!$("#sheet").hidden) showSettings(false); } });

historyControls = installHistoryControls({ api, actions: document.querySelector(".header-actions"), locale: "en", onSnapshot: (detail) => { historyView = (detail.records ?? []).map(normalizeProduct); render(data); }, onCurrent: () => { historyView = undefined; render(data); } });
request("summary").then(render).catch((error) => { data = { products: [], lastError: error.message }; render(data); });
